def analyze_input_data(data):
    if not data:
        return [], {'tied_grades': 0}
    output_list = sorted(data, key=lambda d: d['grade'])
    value_counts = {}
    for entry in data:
        grade_value = entry['grade']
        value_counts[grade_value] = value_counts.get(grade_value, 0) + 1
    tied_count = 0
    for count in value_counts.values():
        if count > 1:
            tied_count += 1
    stats = {'tied_grades': tied_count}
    return output_list, stats
